/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Arrays;public class B4row extends B4box<B4row> {	public static final String row = "row";	public static final String formRow = "form-row";	public static final String noGutters = "no-gutters";	private int[] numbers = null;	public B4row() {		super.cssClass(row);	}	public B4row(boolean form) {		super.cssClass(form ? formRow : row);	}	public B4row device(int... numbers) {		this.numbers = B4col.numbers(numbers);		return this;	}	public B4row device(String device) {		this.numbers = B4col.numbers(device);		return this;	}	public B4row noGutters() {		this.cssClass(noGutters);		return this;	}	@Override	public void build() {		if (this.numbers != null && super.count() > 0) {			super.getContents().forEach(c -> {				if (c instanceof B4col) {					B4col col = (B4col) c;					if (col.getNumbers() == null) {						col.setNumbers(Arrays.copyOf(this.numbers, this.numbers.length));					}				}			});		}		super.build();	}	public int[] getNumbers() {		return numbers;	}	public void setNumbers(int[] numbers) {		this.numbers = numbers;	}	}